y=mx+c \longrightarrow y=m_1x_1+m_2x_2+c
 \longrightarrow 
 \boxed{ y=\beta_0+\beta_1x_1+\beta_2x_2 }

X=\begin{bmatrix}
 1 & x_{11} & \cdots & x_{1n}

 1 & x_{21} & \cdots & x_{2n}

 \vdots & & & \vdots

 1 & x_{m1} & \cdots & x_{mn}
 \end{bmatrix}_{m\times(n+1)},
 \qquad
 \beta=\begin{bmatrix}\beta_0
 \beta_1
 \vdots
 \beta_n\end{bmatrix}.

\Longrightarrow\quad X^{ \top}X\beta=X^{ \top}y
 \quad\Longrightarrow\quad
 \boxed{ \hat\beta=\left(X^{ \top}X\right)^{-1}X^{ \top}y }

\hat\beta = \begin{bmatrix}2
 \tfrac{4}{3}
 \tfrac{2}{3}\end{bmatrix} \quad\Rightarrow\quad \hat y = 2 + \tfrac{4}{3}x_1 + \tfrac{2}{3}x_2
